/* ================= STAGES — board, list, review, new stage, follow-up stages ================= */
S.sg={dir:'out',camp:'k1',tab:'board',flash:{},trOpen:{}};
D.stFollow={ai:false,out:[{if:'No reply to text',after:'4 hours',then:'Call',by:'s3',tpl:'Friendly check-in call'},{if:'Said “call me later”',after:'1 day',then:'Call',by:'s1',tpl:'Quick call-back'},{if:'Replied but not booked',after:'2 days',then:'Move to Pending',by:'s1',tpl:'Let AI write it'}],in:[{if:'No reply to text',after:'15 minutes',then:'Call',by:'s1',tpl:'Quick call-back'},{if:'Missed appointment',after:'1 hour',then:'Text',by:'r1',tpl:'Missed you text'}],drop:{on:true,n:5,cond:'no reply'}};
D.stInstr={out:['Pending leads get a friendly check-in, never a hard sell','After “Order Booked”, the marketing agent asks for a referral'],in:['Inbound leads get a reply within 1 minute','If an inbound lead asks for an appointment, the receptionist takes over']};
D.review=[
 {id:'rv1',cid:'c33',camp:'k2',desc:'We talked to Daniel: he liked the Hicks St condo, asked to move the viewing to 11 AM and said “we might wait until spring”. Please choose the stage.',sugg:'Pending',conf:54,conv:null,rec:1,summary:'Liked the condo; wants to move viewing; might wait until spring.',tr:[['Robert','Hi Daniel, it’s Robert from Keystone Realty — are we still on for Saturday at 10?'],['Daniel','Can we do 11 instead? And honestly we might wait until spring.'],['Robert','Of course, 11 works. Is there anything that would help you decide sooner?'],['Daniel','Not really, we’ll see after the viewing.']]},
 {id:'rv2',cid:'c61',camp:'k4',desc:'Omar asked about the $50 plan on TikTok, gave a postal code in Brampton but didn’t say if he wants to switch. AI isn’t sure between Qualified and New inquiry.',sugg:'Qualified',conf:61,conv:'v8',rec:0,summary:'Asked about price; covered area; no decision yet.',tr:[]},
 {id:'rv3',cid:'c12',camp:'k1',desc:'The customer said “sounds good, send me something by email” on a call. Is this Interested or Order Booked?',sugg:'Interested',conf:58,conv:null,rec:1,summary:'Positive but asked for details by email before deciding.',tr:[['Sarah','Would you like me to book the installation?'],['Customer','Sounds good, send me something by email first.']]},
];
TITLES.stages=()=>'<b>Stages</b> · '+(S.sg.dir==='out'?'Outbound':'Inbound');
function sgCamps(){return D.campaigns.filter(c=>(S.sg.dir==='in'?c.dir==='in':c.dir!=='in'))}
VIEWS.stages=()=>{const cs=sgCamps();if(!cs.find(c=>c.id===S.sg.camp))S.sg.camp=cs[0]?cs[0].id:null;const c=camp(S.sg.camp);const d=S.sg.dir;const L=c?stagesOf(c):[];const rv=D.review.filter(r=>!r.done).length;
 const head=`<div class="ph"><div><h1>Stages</h1><p class="sub">Where every lead is, live. Agents move people the moment they talk — always following the latest message. Drag a card to move it yourself.</p></div><div class="row">${btn('Assign stages to campaigns','stAssign',{k:'sm'})}${btn('Copy to '+(d==='out'?'inbound':'outbound'),'stCopy',{k:'sm',i:'copy',t:'Copy these stages in one click'})}${btn('Edit stages','stEditAll',{k:'sm',i:'edit'})}${btn('New stage','stageNew',{k:'sm primary',i:'plus',a:c?`data-pipe="${c.pipe}" data-dir="${d}"`:''})}</div></div>
 <div class="row nw" style="gap:8px;margin-bottom:14px">${[['out','Outbound stages','out'],['in','Inbound stages','in']].map(([v,l,i])=>`<button class="atype ${d===v?'on':''}" style="flex:0 0 auto;min-width:220px" data-act="sgDir" data-v="${v}"><span class="ico">${ic(i,15)}</span><span><b>${l}</b><span>${D.campaigns.filter(x=>v==='in'?x.dir==='in':x.dir!=='in').length} campaigns</span></span></button>`).join('')}</div>
 <div class="row between" style="margin-bottom:14px"><div class="row">${seg(cs.map(x=>[x.id,x.name.replace(/ — /,' · ')]),S.sg.camp,'sgCamp')}</div>${seg([['board','Board','kanban'],['list','List','rows'],['review',`Review${rv?' ('+rv+')':''}`,'usercheck'],['follow','Follow-up stages','refresh']],S.sg.tab,'sgTab')}</div>`;
 if(!c)return `<div class="page wide">${head}${empty('No '+(d==='in'?'inbound':'outbound')+' campaigns yet.',btn('New campaign','newCamp',{k:'sm primary'}))}</div>`;
 let body='';const cards=D.contacts.filter(x=>x.camp===c.id);
 if(S.sg.tab==='board')body=`<div class="grid" style="grid-template-columns:minmax(0,1fr) 280px;align-items:start"><div class="board" id="board">${L.map(s=>{const cc=cards.filter(x=>x.stage===s.n);const val=s.rev?cc.reduce((a,x)=>a+(x.purchase?x.purchase.amount:0),0):0;return `<div class="bcol" data-col="${esc(s.n)}"><div class="bcol-h"><span style="width:18px;height:18px;border-radius:5px;display:grid;place-items:center;background:${s.c};color:#fff">${ic(s.i,11)}</span>${esc(s.n)}<span class="n">${cc.length}</span>${iconBtn('edit','stageEdit','Edit stage',`data-pipe="${c.pipe}" data-dir="${d}" data-id="${s.id}"`,'xs')}</div><div class="bcol-s">${s.rev?`Revenue ${money(val)}`:esc(s.crit[0]||'')}</div>
  ${cc.map(x=>`<button class="kc ${S.sg.flash[x.id]?'flash':''}" draggable="true" data-card="${x.id}" data-act="kcOpen" data-id="${x.id}"><span class="t">${esc(cname(x))}</span><span class="r"><span class="row nw" style="gap:3px">${c.ch.slice(0,3).map(k=>platIc(k)).join('')}</span>${x.agent?`<span class="ai-tag">${ic('spark',10)}${agName(x.agent)}</span>`:''}</span><span class="r"><span>${agoTxt(x.last)}</span>${s.rev&&x.purchase?`<b style="color:var(--good)">${money(x.purchase.amount)}</b>`:''}</span></button>`).join('')}</div>`}).join('')}</div>
  <div class="card sticky"><div class="card-h"><h3>Live activity</h3>${bdg('<span class="dot"></span>Live','good')}</div><div class="card-b tight feed" id="sgfeed">${D.activity.slice(0,10).map(a=>`<div class="fe ${a.nw?'new':''}"><span class="aimark">${ic(a.i,13)}</span><div>${a.text}<div class="xs faint">${a.time}</div></div></div>`).join('')}</div></div></div>`;
 if(S.sg.tab==='list'){const rv=revStage(c);body=`<div class="card tw"><table class="t"><thead><tr><th>Name</th><th>Stage</th><th>Channel(s)</th><th>Agent</th><th>Last update</th><th class="r">Revenue</th></tr></thead><tbody>${cards.map(x=>{const cv=D.convos.find(v=>v.cid===x.id);return `<tr><td><button class="lnk" data-act="openContact" data-id="${x.id}">${esc(cname(x))}</button></td><td>${sel(L.map(s=>s.n),x.stage,`data-chg="sgStage" data-id="${x.id}" aria-label="Stage"`,'sm auto')}</td><td><span class="row nw" style="gap:3px">${(cv?[cv.plat]:c.ch.slice(0,3)).map(k=>`<button class="plat p-${k}" style="border:0" data-act="${cv?'openConvo':'newChatTo'}" data-id="${cv?cv.id:''}" data-cid="${x.id}" data-tip="<b>${PL[k].l}</b><br>Talked with ${esc(agName(x.agent||c.agents[0]))}${cv?'<br>Click to open the conversation':''}">${ic(PL[k].i,12)}</button>`).join('')}</span></td><td>${x.agent?`<button class="ai-tag" data-act="openAgent" data-id="${x.agent}">${ic('spark',10)}${agName(x.agent)}</button>`:'—'}</td><td class="small">${agoTxt(x.last)}</td><td class="r num">${x.stage===rv&&x.purchase?`<b style="color:var(--good)">${money(x.purchase.amount)}</b>`:''}</td></tr>`}).join('')}</tbody></table></div><p class="small muted" style="margin-top:8px">Revenue shows only at the revenue stage (<b>${esc(rv||'—')}</b>).</p>`}
 if(S.sg.tab==='review')body=`<div class="banner ai" style="margin-bottom:12px">${ic('spark',15)}<span class="small">When the AI can’t confidently choose a stage, the lead waits here. Pick the stage — the item disappears and <b>the AI learns</b> so it won’t ask again for similar cases.</span></div><div class="stack">${D.review.filter(r=>!r.done).map(r=>{const x=byId(r.cid),cp=camp(r.camp);return `<div class="card"><div class="card-b stack-s"><div class="row between"><div class="row"><button class="lnk" style="font-weight:600;font-size:15px" data-act="openContact" data-id="${x.id}">${esc(cname(x))}</button><span class="small muted">${esc(x.phone)} · ${esc(x.city)}</span></div><button class="bdg line" data-act="nav" data-v="campaign" data-p='{"id":"${cp.id}"}'>${dirIc(cp.dir)} ${esc(cp.name)}</button></div><p>${esc(r.desc)}</p>
  ${r.rec?`<div class="callc" style="width:100%"><div class="wave"><button class="pl" data-act="toast" data-m="Playing recording (prototype)" aria-label="Play">${ic('play',12)}</button>${waveSvg()}<span class="small muted">2:14</span></div><div class="small"><b>Call summary:</b> ${esc(r.summary)}</div>${S.sg.trOpen[r.id]?`<div class="tscript">${r.tr.map(l=>`<div><b>${esc(l[0])}:</b> ${esc(l[1])}</div>`).join('')}</div>`:''}<button class="btn link small" style="align-self:flex-start" data-act="rvTr" data-id="${r.id}">${S.sg.trOpen[r.id]?'Hide':'Show'} transcript</button></div>`:''}
  <div class="row">${r.conv?btn('Open conversation','openConvo',{k:'sm',i:'sms',a:`data-id="${r.conv}"`}):''}<span class="small muted">AI suggests <b>${esc(r.sugg)}</b> (${r.conf}% sure)</span><span class="grow"></span>${sel(stagesOf(cp).map(s=>s.n),r.sugg,`id="rvS-${r.id}" aria-label="Choose stage"`,'sm auto')}${btn('Save stage','rvSave',{k:'sm primary',a:`data-id="${r.id}"`})}</div></div></div>`}).join('')||`<div class="card">${empty('Nothing to review — the AI is confident about every lead.')}</div>`}</div>`;
 if(S.sg.tab==='follow')body=`<div class="grid g2" style="align-items:start"><div class="card"><div class="card-h"><h3>Follow-up conditions</h3><span class="small muted">Used by every campaign on these stages</span></div><div class="card-b stack">${fuHTML('st','Campaign and agent follow-up settings can override these.')}</div></div><div class="card"><div class="card-h"><h3>Follow-up instructions · ${d==='out'?'Outbound':'Inbound'}</h3>${btn('Copy to '+(d==='out'?'inbound':'outbound'),'stInstrCopy',{k:'xs',i:'copy'})}</div><div class="card-b">${led('stinstr'+d,D.stInstr[d],'Add an instruction, e.g. “Pending leads get a check-in after 3 days”')}</div></div></div>`;
 return `<div class="page wide" style="max-width:1560px">${head}${body}</div>`};
AFTER.stages=()=>{if(S.sg.tab!=='board')return;let drag=null;$$('.kc').forEach(el=>{el.addEventListener('dragstart',e=>{drag=el.dataset.card;el.classList.add('drag');try{e.dataTransfer.setData('text/plain',drag)}catch(_){}});el.addEventListener('dragend',()=>el.classList.remove('drag'))});$$('.bcol').forEach(col=>{col.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('over')});col.addEventListener('dragleave',()=>col.classList.remove('over'));col.addEventListener('drop',e=>{e.preventDefault();col.classList.remove('over');if(drag)moveLead(drag,col.dataset.col,'you')})})};
function moveLead(cid,stage,by){const x=byId(cid);if(!x||x.stage===stage)return;const from=x.stage;x.stage=stage;x.last=0;const c=camp(x.camp);if(c&&stage===revStage(c)&&!x.purchase){const it=D.products[c.id].cats[0].items[0];x.purchase={product:it[0],amount:it[1],date:dISO(0)};x.sold=dISO(0)}
 D.activity.unshift({i:'kanban',text:`${by==='you'?'<b>You</b>':'<b>'+agName(by)+'</b>'} moved <b>${esc(cname(x))}</b> from ${esc(from)} to <b>${esc(stage)}</b>`,time:'just now',k:'stage',nw:1});
 const cv=D.convos.find(v=>v.cid===cid);if(cv)cv.items.push(ev('stage',`Stage moved to ${stage} by ${by==='you'?'you':agName(by)}`,'now',{stage}));
 S.sg.flash[cid]=1;setTimeout(()=>{delete S.sg.flash[cid];const el=$(`.kc[data-card="${cid}"]`);if(el)el.classList.remove('flash')},2200);
 if(S.view==='stages')rr();if(by==='you')toast(`${cname(x)} moved to ${stage} — updated everywhere`)}
A.sgDir=el=>{S.sg.dir=el.dataset.v;S.sg.camp=null;rr();renderTop()};
A.sgCamp=el=>{S.sg.camp=el.dataset.v;rr()};A.sgTab=el=>{S.sg.tab=el.dataset.v;rr()};
C.sgStage=el=>moveLead(el.dataset.id,el.value,'you');
A.kcOpen=el=>{const x=byId(el.dataset.id),c=camp(x.camp);openM('kcMove',{id:x.id})};
M.kcMove=m=>{const x=byId(m.id),c=camp(x.camp);const cv=D.convos.find(v=>v.cid===x.id);return MS(esc(cname(x)),`<div class="lbl">Move to stage</div><div class="choice">${stagesOf(c).map(s=>`<button class="${x.stage===s.n?'on':''}" data-act="kcTo" data-v="${esc(s.n)}"><i style="width:8px;height:8px;border-radius:2px;background:${s.c}"></i>${esc(s.n)}</button>`).join('')}</div><dl class="kv"><dt>Campaign</dt><dd>${esc(c.name)}</dd><dt>Agent</dt><dd>${x.agent?agName(x.agent):'—'}</dd><dt>Lead source</dt><dd>${dirIc(x.dir)} ${esc(x.source)}</dd><dt>Folder</dt><dd>${esc(fName(x.folder))}</dd></dl>`,`${cv?btn('Open conversation','openConvo',{k:'',a:`data-id="${cv.id}"`}):''}${btn('Open profile','openContact',{k:'',a:`data-id="${x.id}"`})}${btn('Done','close',{k:'primary'})}`,'n')};
A.kcTo=el=>{const id=S.modal.id;closeM();moveLead(id,el.dataset.v,'you')};
A.rvTr=el=>{S.sg.trOpen[el.dataset.id]=!S.sg.trOpen[el.dataset.id];rr()};
A.rvSave=el=>{const r=D.review.find(x=>x.id===el.dataset.id);const v=$('#rvS-'+r.id).value;r.done=true;const x=byId(r.cid);x.stage=v;rr();toast(`${cname(x)} set to ${v}. The AI learned from this — similar cases won’t come back to you.`,true)};
A.stCopy=()=>{const c=camp(S.sg.camp);const from=S.sg.dir,to=from==='out'?'in':'out';D.stages[c.pipe][to]=clone(D.stages[c.pipe][from]).map(s=>Object.assign(s,{id:uid('st')}));toast(`Copied ${D.stages[c.pipe][from].length} stages to ${to==='in'?'inbound':'outbound'}`)};
A.stInstrCopy=()=>{const d=S.sg.dir;D.stInstr[d==='out'?'in':'out']=D.stInstr[d].slice();toast('Instructions copied')};
A.stAssign=()=>openM('stAssign',{pipe:camp(S.sg.camp).pipe});
M.stAssign=m=>MS('Assign stages to campaigns',`${fld('Stage set',sel(Object.keys(D.stages).map(k=>[k,{telecom:'Telecom',realestate:'Real estate',dental:'Dental'}[k]||'Custom']),m.pipe,'data-chg="saPipe"'))}<p class="small muted">Campaigns ticked below follow these stages (outbound campaigns use the outbound set, inbound ones the inbound set). You can still edit stages inside each campaign.</p>${D.campaigns.map(c=>`<label class="chk" style="padding:6px 0"><input type="checkbox" data-chg="saC" value="${c.id}" ${c.pipe===m.pipe?'checked':''}>${dirIc(c.dir)} ${esc(c.name)}</label>`).join('')}<div class="row">${btn('Select all','saAll',{k:'xs'})}</div>`,btn('Done','close',{k:'primary'}),'n');
C.saPipe=el=>{S.modal.pipe=el.value;renderModal()};C.saC=el=>{const c=camp(el.value);if(el.checked){c.pipe=S.modal.pipe;toast(c.name+' now follows these stages')}};
A.saAll=()=>{D.campaigns.forEach(c=>c.pipe=S.modal.pipe);renderModal();toast('All campaigns follow these stages')};
/* new / edit stage */
const ST_COLORS=['#8A93A6','#4C8BF5','#266DF0','#7048E8','#C68A12','#0F766E','#15803D','#D92D20','#DB2777','#6B6B6B'];
const ST_ICONS=['user','send','star','clock','check','package','zap','calendar','file','pin','dollar','x','minus','query','heart','flag','phone','mail'];
A.stageNew=el=>{const pipe=el.dataset.pipe||camp(S.sg.camp).pipe,dir=el.dataset.dir||S.sg.dir;openM('stage',{pipe,dir,edit:null,s:{id:uid('st'),n:'',c:'#7048E8',i:'star',crit:[],rev:false,t:'open'},camps:D.campaigns.filter(c=>c.pipe===pipe&&(dir==='in'?c.dir==='in':c.dir!=='in')).map(c=>c.id),after:''})};
A.stageEdit=el=>{const s=D.stages[el.dataset.pipe][el.dataset.dir].find(x=>x.id===el.dataset.id);openM('stage',{pipe:el.dataset.pipe,dir:el.dataset.dir,edit:s.id,s:clone(s),camps:D.campaigns.filter(c=>c.pipe===el.dataset.pipe).map(c=>c.id)})};
M.stageNew=m=>M.stage(m);
M.stage=m=>{const s=m.s;const L=D.stages[m.pipe][m.dir];return MS(m.edit?'Edit stage':'New stage',`<div class="fgrid two">${fld('Stage name',`<input class="in" value="${esc(s.n)}" placeholder="e.g. Qualified" data-inp="stN" data-autofocus>`)}${fld('Type',sel([['open','In progress'],['pending','Pending'],['won','Won'],['lost','Lost']],s.t,'data-chg="stT"'))}</div>
 <div class="fgrid two">${fld('Colour',`<div class="colors">${ST_COLORS.map(c=>`<button class="${s.c===c?'on':''}" style="background:${c}" data-act="stC" data-v="${c}" aria-label="Colour ${c}"></button>`).join('')}</div>`)}${fld('Icon',`<div class="icons">${ST_ICONS.map(i=>`<button class="${s.i===i?'on':''}" data-act="stI" data-v="${i}" aria-label="${i}">${ic(i,14)}</button>`).join('')}</div>`)}</div>
 ${fld('When does a lead enter this stage? — one full sentence per line',led('stcrit',s.crit,'e.g. Customer says “OK, go ahead”',{sample:'Customer says yes I need this'}),'The AI reads calls, texts and emails and always follows the latest message. If a human is chatting and a lead matches, they get a pop-up to move it.')}
 <div class="row">${aiBtn('Write criteria with AI','stAIcrit','','sm')}</div>
 ${optRow(`${ic('dollar',14)} Count revenue at this stage`,'Revenue from the campaign’s products is added when a lead reaches this stage',sw(s.rev,'stRev'))}
 ${m.edit?'':fld('Put it after',sel([['','At the end']].concat(L.map(x=>[x.id,x.n])),m.after,'data-chg="stAfter"'))}
 ${fld('Assign to campaigns',`<div class="stack-s">${D.campaigns.filter(c=>m.dir==='in'?c.dir==='in':c.dir!=='in').map(c=>`<label class="chk"><input type="checkbox" data-chg="stCamp" value="${c.id}" ${m.camps.includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join('')}<button class="btn link small" style="align-self:flex-start" data-act="stCampAll">Assign to all ${m.dir==='in'?'inbound':'outbound'} campaigns</button></div>`)}`,`${m.edit?btn('Delete stage','stDel',{k:'danger ghost'}):''}${btn('Cancel','close',{k:'ghost'})}${btn(m.edit?'Save stage':'Create stage','stSave',{k:'primary'})}`,'w')};
I.stN=el=>{S.modal.s.n=el.value};C.stT=el=>{S.modal.s.t=el.value};A.stC=el=>{S.modal.s.c=el.dataset.v;renderModal()};A.stI=el=>{S.modal.s.i=el.dataset.v;renderModal()};A.stRev=el=>{S.modal.s.rev=el.checked};C.stAfter=el=>{S.modal.after=el.value};
C.stCamp=el=>{const a=S.modal.camps,i=a.indexOf(el.value);el.checked?i<0&&a.push(el.value):a.splice(i,1)};
A.stCampAll=()=>{S.modal.camps=D.campaigns.filter(c=>S.modal.dir==='in'?c.dir==='in':c.dir!=='in').map(c=>c.id);renderModal()};
A.stAIcrit=()=>{const s=S.modal.s;const n=(s.n||'this stage').toLowerCase();s.crit.push(`Customer says they are ready to go ahead with ${n==='this stage'?'the offer':'it'}`,'Customer confirms the details back to the agent','Customer meets all required qualifying questions');renderModal();toast('AI added 3 criteria — edit or remove any',true)};
A.stSave=()=>{const m=S.modal,s=m.s;if(!s.n.trim()){toast('Give the stage a name');return}if(!s.crit.length){toast('Add at least one sentence for when a lead enters this stage');return}const L=D.stages[m.pipe][m.dir];if(m.edit){const i=L.findIndex(x=>x.id===m.edit);const old=L[i].n;L[i]=s;if(old!==s.n)D.contacts.forEach(c=>{if(c.stage===old)c.stage=s.n})}else{const i=m.after?L.findIndex(x=>x.id===m.after)+1:L.length;L.splice(i,0,s)}m.camps.forEach(k=>{camp(k).pipe=m.pipe});closeM();rr();toast(m.edit?'Stage saved — updated everywhere':`Stage “${s.n}” created`)};
A.stDel=()=>{const m=S.modal,L=D.stages[m.pipe][m.dir];const s=L.find(x=>x.id===m.edit);const n=D.contacts.filter(c=>c.stage===s.n).length;D.stages[m.pipe][m.dir]=L.filter(x=>x.id!==m.edit);D.contacts.forEach(c=>{if(c.stage===s.n)c.stage=L[0].n});closeM();rr();toast(`Stage deleted — ${n} leads moved to ${L[0].n}`)};
A.stEditAll=()=>{const c=camp(S.sg.camp);openM('stAll',{pipe:c.pipe,dir:S.sg.dir})};
M.stAll=m=>{const L=D.stages[m.pipe][m.dir];return MS(`Edit ${m.dir==='out'?'outbound':'inbound'} stages`,`<div class="card">${L.map((s,i)=>`<div class="lr"><span style="width:22px;height:22px;border-radius:6px;background:${s.c};color:#fff;display:grid;place-items:center">${ic(s.i,12)}</span><span class="m"><div class="t1">${esc(s.n)} ${s.rev?bdg('Revenue','good'):''}${s.t!=='open'?' '+bdg(s.t):''}</div><div class="t2">${s.crit.map(esc).join(' · ')}</div></span>${iconBtn('up','stMove','Move up',`data-i="${i}" data-d="-1"`,'xs')}${iconBtn('dn','stMove','Move down',`data-i="${i}" data-d="1"`,'xs')}${btn('Edit','stageEdit',{k:'xs',a:`data-pipe="${m.pipe}" data-dir="${m.dir}" data-id="${s.id}"`})}</div>`).join('')}</div>`,`${btn('New stage','stageNew',{k:'',i:'plus',a:`data-pipe="${m.pipe}" data-dir="${m.dir}"`})}${btn('Done','close',{k:'primary'})}`,'w')};
A.stMove=el=>{const m=S.modal,L=D.stages[m.pipe][m.dir],i=+el.dataset.i,j=i+ +el.dataset.d;if(j<0||j>=L.length)return;[L[i],L[j]]=[L[j],L[i]];renderModal();if(S.view==='stages')rr()};
